package com.slayerspeed.tracking;

import com.slayerspeed.model.ActiveTask;

public class ActiveTimeTracker
{
	public void recordActivity(ActiveTask task, long nowMillis, int idleTimeoutMinutes)
	{
		long previous = task.getLastActivityAtMillis();
		if (previous <= 0)
		{
			if (task.getSetupMillis() == 0)
			{
				task.setSetupMillis(Math.max(0L, nowMillis - task.getStartedAtMillis()));
			}
			task.setLastActivityAtMillis(nowMillis);
			return;
		}

		long gap = Math.max(0L, nowMillis - previous);
		long cap = Math.max(1, idleTimeoutMinutes) * 60_000L;
		task.addActiveMillis(Math.min(gap, cap));
		task.setLastActivityAtMillis(nowMillis);
	}

	public void pause(ActiveTask task)
	{
		if (task != null)
		{
			task.setLastActivityAtMillis(0L);
		}
	}
}

package com.slayerspeed.tracking;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class AttributionResult
{
	public static final AttributionResult NONE = new AttributionResult(0, 0);

	private final int literalKills;
	private final int slayerXp;
	private final List<String> confirmedNpcNames;

	public AttributionResult(int literalKills, int slayerXp)
	{
		this(literalKills, slayerXp, Collections.emptyList());
	}

	public AttributionResult(int literalKills, int slayerXp, List<String> confirmedNpcNames)
	{
		this.literalKills = literalKills;
		this.slayerXp = slayerXp;
		this.confirmedNpcNames = confirmedNpcNames == null || confirmedNpcNames.isEmpty()
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(confirmedNpcNames));
	}

	public int getLiteralKills()
	{
		return literalKills;
	}

	public int getSlayerXp()
	{
		return slayerXp;
	}

	public List<String> getConfirmedNpcNames()
	{
		return confirmedNpcNames;
	}

	public AttributionResult plus(AttributionResult other)
	{
		List<String> names = new ArrayList<>(confirmedNpcNames);
		names.addAll(other.confirmedNpcNames);
		return new AttributionResult(
			literalKills + other.literalKills,
			slayerXp + other.slayerXp,
			names);
	}
}

package com.slayerspeed.tracking;

final class CandidateDeath
{
	private final Object npcIdentity;
	private final int npcId;
	private final String npcName;
	private final int deathTick;
	private final boolean interacted;
	private boolean xpMatched;
	private boolean progressMatched;
	private boolean lootMatched;
	private boolean confirmed;
	private ProgressBatch progressBatch;
	private boolean batchEvidenceCounted;

	CandidateDeath(Object npcIdentity, int npcId, String npcName, int deathTick, boolean interacted)
	{
		this.npcIdentity = npcIdentity;
		this.npcId = npcId;
		this.npcName = npcName;
		this.deathTick = deathTick;
		this.interacted = interacted;
	}

	Object getNpcIdentity()
	{
		return npcIdentity;
	}

	int getNpcId()
	{
		return npcId;
	}

	String getNpcName()
	{
		return npcName;
	}

	int getDeathTick()
	{
		return deathTick;
	}

	boolean isInteracted()
	{
		return interacted;
	}

	boolean isXpMatched()
	{
		return xpMatched;
	}

	void setXpMatched()
	{
		xpMatched = true;
	}

	boolean isProgressMatched()
	{
		return progressMatched;
	}

	void setProgressMatched()
	{
		progressMatched = true;
	}

	void setLootMatched()
	{
		lootMatched = true;
	}

	boolean isConfirmed()
	{
		return confirmed;
	}

	boolean shouldConfirm()
	{
		return xpMatched || lootMatched || (progressMatched && interacted);
	}

	boolean hasProgressBatch()
	{
		return progressBatch != null;
	}

	void assignProgressBatch(ProgressBatch progressBatch)
	{
		this.progressBatch = progressBatch;
		progressMatched = true;
	}

	boolean recordBatchEvidence()
	{
		if (progressBatch == null || batchEvidenceCounted)
		{
			return false;
		}
		batchEvidenceCounted = true;
		return progressBatch.recordEvidence();
	}

	void confirm()
	{
		confirmed = true;
	}

	static final class ProgressBatch
	{
		private int reportedKills;
		private int evidencedKills;

		ProgressBatch(int reportedKills)
		{
			this.reportedKills = reportedKills;
		}

		boolean recordEvidence()
		{
			evidencedKills++;
			if (evidencedKills > reportedKills)
			{
				reportedKills++;
				return true;
			}
			return false;
		}
	}
}

package com.slayerspeed.tracking;

import javax.inject.Inject;

/** Tracks fired cannon ammo while excluding reloads and ammunition returned to inventory. */
public class CannonballTracker
{
	private int lastLoaded = -1;
	private int lastInventoryCannonballs = -1;
	private boolean cannonPlaced;
	private int pendingConsumed;

	@Inject
	public CannonballTracker()
	{
	}

	public void reset(int loaded, boolean placed, int inventoryCannonballs)
	{
		lastLoaded = Math.max(0, loaded);
		lastInventoryCannonballs = Math.max(0, inventoryCannonballs);
		cannonPlaced = placed;
		pendingConsumed = 0;
	}

	public void clear()
	{
		lastLoaded = -1;
		lastInventoryCannonballs = -1;
		cannonPlaced = false;
		pendingConsumed = 0;
	}

	public void setCannonPlaced(boolean placed)
	{
		cannonPlaced = placed;
	}

	public void observeLoaded(int loaded, boolean trackingEligibleTask)
	{
		int current = Math.max(0, loaded);
		if (lastLoaded >= 0 && cannonPlaced && trackingEligibleTask && current < lastLoaded)
		{
			pendingConsumed += lastLoaded - current;
		}
		lastLoaded = current;
	}

	/**
	 * Commits decreases after the tick's state updates have settled. Reaching zero while
	 * ammunition returns to inventory indicates Empty; only any unmatched decrease was fired.
	 * Picking up the cannon is excluded separately by the placed state.
	 */
	public int drainConsumed(boolean trackingEligibleTask, int inventoryCannonballs)
	{
		int currentInventoryCannonballs = Math.max(0, inventoryCannonballs);
		int loadedDecrease = pendingConsumed;
		int consumed = cannonPlaced && trackingEligibleTask ? loadedDecrease : 0;
		if (consumed > 0 && lastLoaded == 0 && lastInventoryCannonballs >= 0)
		{
			int returned = Math.max(0, currentInventoryCannonballs - lastInventoryCannonballs);
			consumed = Math.max(0, consumed - Math.min(loadedDecrease, returned));
		}
		pendingConsumed = 0;
		lastInventoryCannonballs = currentInventoryCannonballs;
		return consumed;
	}
}

