			"screaming twisted banshee", "giant rockslug", "cockathrice", "flaming pyrelord",
			"monstrous basilisk", "malevolent mage", "insatiable bloodveld",
			"insatiable mutated bloodveld", "vitreous jelly", "vitreous warped jelly",
			"cave abomination", "abhorrent spectre", "repugnant spectre", "shadow wyrm");
	}

	public EncounterProfile resolve(String taskName, String npcName)
	{
		String normalizedNpc = normalize(npcName);
		if (normalizedNpc.isEmpty() || SUPERIOR_NAMES.contains(normalizedNpc))
		{
			return null;
		}

		Map<String, EncounterProfile> taskProfiles = DETECTION_BY_TASK.get(normalize(taskName));
		if (taskProfiles != null)
		{
			EncounterProfile known = taskProfiles.get(normalizedNpc);
			if (known != null)
			{
				return known;
			}
		}
		return new EncounterProfile("npc:" + normalizedNpc.replace(' ', '-'), cleanDisplayName(npcName));
	}

	public List<EncounterProfile> suggestionsForTask(String taskName)
	{
		List<EncounterProfile> suggestions = SUGGESTIONS_BY_TASK.get(normalize(taskName));
		return suggestions == null ? Collections.emptyList() : suggestions;
	}

	private static void addKrakenTask(String taskName)
	{
		add(taskName, "npc:cave-kraken", "Cave krakens (regular)", "cave kraken");
		add(taskName, "boss:kraken", "Kraken (boss)", "kraken");
	}

	private static void add(String taskName, String id, String displayName, String... npcNames)
	{
		String task = normalize(taskName);
		EncounterProfile profile = new EncounterProfile(id, displayName);
		LinkedHashMap<String, EncounterProfile> detection = DETECTION_BY_TASK.computeIfAbsent(
			task, ignored -> new LinkedHashMap<>());
		for (String npcName : npcNames)
		{
			detection.put(normalize(npcName), profile);
		}
		List<EncounterProfile> suggestions = SUGGESTIONS_BY_TASK.computeIfAbsent(
			task, ignored -> new ArrayList<>());
		if (!suggestions.contains(profile))
		{
			suggestions.add(profile);
		}
	}

	private static String normalize(String value)
	{
		return value == null
			? ""
			: value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ENGLISH);
	}

	private static String cleanDisplayName(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return "Unknown monster";
		}
		return value.trim().replaceAll("\\s+", " ");
	}
}

package com.slayerspeed.tracking;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class KillAttributionService
{
	private static final int CORRELATION_TICKS = 2;
	private static final int EXPIRY_TICKS = 4;

	private final Deque<CandidateDeath> candidates = new ArrayDeque<>();
	private final Deque<PendingXp> pendingXp = new ArrayDeque<>();
	private int lastTaskProgressTick = Integer.MIN_VALUE;

	public AttributionResult onCandidateDeath(Object identity, int npcId, String npcName, boolean interacted, int tick)
	{
		for (CandidateDeath existing : candidates)
		{
			if (existing.getNpcIdentity() == identity && withinWindow(existing.getDeathTick(), tick))
			{
				return AttributionResult.NONE;
			}
		}

		CandidateDeath candidate = new CandidateDeath(identity, npcId, npcName, tick, interacted);
		candidates.addLast(candidate);
		log.debug("Candidate Slayer death: {} ({}) on tick {}", npcName, npcId, tick);

		PendingXp xp = candidate.isInteracted() ? findPendingXp(tick) : null;
		if (xp != null)
		{
			pendingXp.remove(xp);
			candidate.setXpMatched();
			return confirm(candidate, xp.amount);
		}
		return AttributionResult.NONE;
	}

	public AttributionResult onSlayerXp(int xp, int tick)
	{
		return onSlayerXp(xp, tick, true);
	}

	public AttributionResult onSlayerXp(int xp, int tick, boolean allowTaskProgressCorrelation)
	{
		if (xp <= 0)
		{
			return AttributionResult.NONE;
		}
		CandidateDeath candidate = findCandidateForXp(tick);
		if (candidate == null)
		{
			if (allowTaskProgressCorrelation
				&& lastTaskProgressTick != Integer.MIN_VALUE
				&& withinWindow(lastTaskProgressTick, tick))
			{
				return new AttributionResult(0, xp);
			}
			pendingXp.addLast(new PendingXp(xp, tick));
			return AttributionResult.NONE;
		}
		candidate.setXpMatched();
		return confirm(candidate, xp);
	}

	public AttributionResult onTaskProgress(int progressUnits, int tick)
	{
		if (progressUnits > 0)
		{
			lastTaskProgressTick = tick;
		}
		int kills = 0;
		List<String> confirmedNpcNames = new ArrayList<>();
		List<CandidateDeath> batchCandidates = progressUnits > 0
			? findCandidatesForProgress(tick)
			: new ArrayList<>();
		if (!batchCandidates.isEmpty())
		{
			kills = Math.min(progressUnits, batchCandidates.size());
			CandidateDeath.ProgressBatch batch = new CandidateDeath.ProgressBatch(kills);
			for (CandidateDeath candidate : batchCandidates)
			{
				candidate.assignProgressBatch(batch);
			}
			for (int index = 0; index < kills; index++)
			{
				confirmedNpcNames.add(batchCandidates.get(index).getNpcName());
			}
			log.debug("Confirmed {} Slayer kills from {} simultaneous candidates and {} progress units",
				kills, batchCandidates.size(), progressUnits);
		}

		int xpAmount = 0;
		if (progressUnits > 0)
		{
			PendingXp xp = findPendingXp(tick);
			if (xp != null)
			{
				pendingXp.remove(xp);
				xpAmount = xp.amount;
			}
		}
		return kills == 0 && xpAmount == 0
			? AttributionResult.NONE
			: new AttributionResult(kills, xpAmount, confirmedNpcNames);
	}

	public AttributionResult onLoot(Object identity, int npcId, int tick)
	{
		CandidateDeath candidate = findCandidateForLoot(identity, npcId, tick);
		if (candidate != null)
		{
			candidate.setLootMatched();
			PendingXp xp = !candidate.isXpMatched() ? findPendingXp(tick) : null;
			if (xp != null)
			{
				pendingXp.remove(xp);
				candidate.setXpMatched();
			}
			return confirm(candidate, xp == null ? 0 : xp.amount);
		}
		return AttributionResult.NONE;
	}

	public void advanceTick(int tick)
	{
		candidates.removeIf(candidate -> tick - candidate.getDeathTick() > EXPIRY_TICKS);
		pendingXp.removeIf(xp -> tick - xp.tick > EXPIRY_TICKS);
	}

	public void reset()
	{
		candidates.clear();
		pendingXp.clear();
		lastTaskProgressTick = Integer.MIN_VALUE;
	}

	public int consumePendingXpForCompletion(int tick)
	{
		PendingXp xp = findPendingXp(tick);
		if (xp == null)
		{
			return 0;
		}
		pendingXp.remove(xp);
		return xp.amount;
	}

	private AttributionResult confirm(CandidateDeath candidate, int xp)
	{
		int kills = 0;
		if (!candidate.isConfirmed() && candidate.shouldConfirm())
		{
			candidate.confirm();
			kills = candidate.hasProgressBatch()
				? (candidate.recordBatchEvidence() ? 1 : 0)
				: 1;
			log.debug("Confirmed Slayer kill: {}", candidate.getNpcName());
		}
		return kills == 0 && xp == 0
			? AttributionResult.NONE
			: new AttributionResult(
				kills,
				xp,
				kills > 0 ? Collections.singletonList(candidate.getNpcName()) : Collections.emptyList());
	}

	private CandidateDeath findCandidateForXp(int tick)
	{
		CandidateDeath onlyInteractedCandidate = null;
		int interactedCount = 0;
		Iterator<CandidateDeath> iterator = candidates.descendingIterator();
		while (iterator.hasNext())
		{
			CandidateDeath candidate = iterator.next();
			if (!candidate.isXpMatched() && withinWindow(candidate.getDeathTick(), tick))
			{
				if (candidate.isInteracted())
				{
					interactedCount++;
					onlyInteractedCandidate = candidate;
				}
			}
		}
		if (interactedCount == 1)
		{
			return onlyInteractedCandidate;
		}
		return null;
	}

	private PendingXp findPendingXp(int tick)
	{
		Iterator<PendingXp> iterator = pendingXp.descendingIterator();
		while (iterator.hasNext())
		{
			PendingXp xp = iterator.next();
			if (withinWindow(xp.tick, tick))
			{
				return xp;
			}
		}
		return null;
	}

	private List<CandidateDeath> findCandidatesForProgress(int tick)
	{
		List<CandidateDeath> matches = new ArrayList<>();
		Iterator<CandidateDeath> iterator = candidates.descendingIterator();
		while (iterator.hasNext())
		{
			CandidateDeath candidate = iterator.next();
			if (!candidate.isConfirmed()
				&& !candidate.hasProgressBatch()
				&& withinWindow(candidate.getDeathTick(), tick))
			{
				matches.add(candidate);
			}
		}
		return matches;
	}

	private CandidateDeath findCandidateForLoot(Object identity, int npcId, int tick)
	{
		Iterator<CandidateDeath> iterator = candidates.descendingIterator();
		while (iterator.hasNext())
		{
			CandidateDeath candidate = iterator.next();
			if (candidate.getNpcIdentity() == identity && withinWindow(candidate.getDeathTick(), tick))
			{
				return candidate;
			}
		}

		if (identity == null)
		{
			iterator = candidates.descendingIterator();
			while (iterator.hasNext())
			{
				CandidateDeath candidate = iterator.next();
				if (candidate.getNpcId() == npcId && withinWindow(candidate.getDeathTick(), tick))
				{
					return candidate;
				}
			}
		}
		return null;
	}

	private static boolean withinWindow(int firstTick, int secondTick)
	{
		return Math.abs(firstTick - secondTick) <= CORRELATION_TICKS;
	}

	private static final class PendingXp
	{
		private final int amount;
		private final int tick;

		private PendingXp(int amount, int tick)
		{
			this.amount = amount;
			this.tick = tick;
		}
	}
}

package com.slayerspeed.tracking;

import java.util.OptionalInt;

public class SlayerXpTracker
{
	private Integer previousXp;

	public OptionalInt observe(int currentXp)
	{
		if (previousXp == null)
		{
			previousXp = currentXp;
			return OptionalInt.empty();
		}

		int delta = currentXp - previousXp;
		previousXp = currentXp;
		return delta > 0 ? OptionalInt.of(delta) : OptionalInt.empty();
	}

	public void reset()
	{
		previousXp = null;
	}

	public void setBaseline(int currentXp)
	{
		previousXp = currentXp;
	}

	public boolean hasBaseline()
	{
		return previousXp != null;
	}
}

package com.slayerspeed.tracking;

public final class TaskSnapshot
{
	private final String taskName;
	private final String taskLocation;
	private final int initialAmount;
	private final int remainingAmount;

	private TaskSnapshot(String taskName, String taskLocation, int initialAmount, int remainingAmount)
	{
		this.taskName = taskName;
		this.taskLocation = taskLocation;
		this.initialAmount = initialAmount;
		this.remainingAmount = remainingAmount;
	}

	public static TaskSnapshot active(String taskName, String taskLocation, int initialAmount, int remainingAmount)
	{
		return new TaskSnapshot(taskName, taskLocation, initialAmount, remainingAmount);
	}

	public static TaskSnapshot none()
	{
		return new TaskSnapshot(null, null, 0, 0);
	}

	public boolean hasTask()
	{
		return taskName != null && !taskName.trim().isEmpty() && remainingAmount > 0;
	}

	public String getTaskName()
	{
		return taskName;
	}

	public String getTaskLocation()
	{
		return taskLocation;
	}

	public int getInitialAmount()
	{
		return initialAmount;
	}

	public int getRemainingAmount()
	{
		return remainingAmount;
	}
}

package com.slayerspeed.tracking;

import com.slayerspeed.model.ActiveTask;
import com.slayerspeed.model.TaskKey;
import com.slayerspeed.model.TaskRun;
import com.slayerspeed.model.TaskRunStatus;
import com.slayerspeed.persistence.TaskHistoryStore;
import javax.inject.Inject;

public class TaskTracker
{
	private static final long CHECKPOINT_INTERVAL_MILLIS = 15_000L;
	static final long COMPLETION_GRACE_MILLIS = 1_800L;

	private final TaskHistoryStore repository;
	private final ActiveTimeTracker activeTimeTracker;
	private ActiveTask activeTask;
	private boolean needsRebaselineAfterLoad;
	private long taskMissingSinceMillis;
	private long completionConfirmedAtMillis;

	@Inject
	public TaskTracker(TaskHistoryStore repository, ActiveTimeTracker activeTimeTracker)
	{
		this.repository = repository;
		this.activeTimeTracker = activeTimeTracker;
	}

	public void loadProfile()
	{
		repository.loadProfile();
		activeTask = repository.getCheckpoint();
		activeTimeTracker.pause(activeTask);
		needsRebaselineAfterLoad = activeTask != null;
		taskMissingSinceMillis = 0L;
		completionConfirmedAtMillis = activeTask == null ? 0L : activeTask.getCompletionConfirmedAtMillis();
	}

	public TaskUpdate observe(
		TaskSnapshot snapshot,
		long nowMillis,
		int idleTimeoutMinutes,
		boolean separateByLocation,
		int maximumRecentRuns)
	{
		if (activeTask == null)
		{
			if (snapshot.hasTask())
			{
				activeTask = start(snapshot, nowMillis);
				repository.saveCheckpoint(activeTask);
				return new TaskUpdate(0, true, null);
			}
			return TaskUpdate.none();
		}

		if (!snapshot.hasTask())
		{
			if (taskMissingSinceMillis == 0L)
			{
				taskMissingSinceMillis = nowMillis;
				return TaskUpdate.none();
			}

			long graceStartedAt = completionConfirmedAtMillis > 0L
				? completionConfirmedAtMillis
				: taskMissingSinceMillis;
			if (nowMillis - graceStartedAt < COMPLETION_GRACE_MILLIS)
			{
				return TaskUpdate.none();
			}

			TaskRunStatus status = completionConfirmedAtMillis > 0L
				? TaskRunStatus.COMPLETED
				: TaskRunStatus.UNKNOWN_INCOMPLETE;
			TaskRun ended = finish(status, nowMillis, separateByLocation, maximumRecentRuns);
			return new TaskUpdate(0, false, ended);
		}

		if (!sameAssignment(activeTask, snapshot))
		{
			TaskRun ended = finish(completionConfirmedAtMillis > 0L ? TaskRunStatus.COMPLETED : TaskRunStatus.REPLACED,
				nowMillis, separateByLocation, maximumRecentRuns);
			activeTask = start(snapshot, nowMillis);
			repository.saveCheckpoint(activeTask);
			return new TaskUpdate(0, true, ended);
		}

		taskMissingSinceMillis = 0L;
		if (completionConfirmedAtMillis > 0L)
		{
			// The Slayer service can expose its previous positive remainder for a tick after
			// the completion message. Do not overwrite the authoritative terminal zero.
			if (nowMillis - completionConfirmedAtMillis < COMPLETION_GRACE_MILLIS)
			{
				return TaskUpdate.none();
			}

			TaskRun ended = finish(TaskRunStatus.COMPLETED, nowMillis, separateByLocation, maximumRecentRuns);
			activeTask = start(snapshot, nowMillis);
			repository.saveCheckpoint(activeTask);
			return new TaskUpdate(0, true, ended);
		}

		if (needsRebaselineAfterLoad)
		{
			needsRebaselineAfterLoad = false;
			activeTask.setLastRemainingAmount(snapshot.getRemainingAmount());
			repository.saveCheckpoint(activeTask);
			return TaskUpdate.none();
		}

		int previous = activeTask.getLastRemainingAmount();
		int current = snapshot.getRemainingAmount();
		activeTask.setLastRemainingAmount(current);
		int progress = Math.max(0, previous - current);
		if (progress > 0)
		{
			activeTask.addProgressUnits(progress);
			activeTimeTracker.recordActivity(activeTask, nowMillis, idleTimeoutMinutes);
			checkpointIfDue(nowMillis);
		}
		return progress > 0 ? new TaskUpdate(progress, false, null) : TaskUpdate.none();
	}

	public void applyAttribution(int literalKills, int slayerXp, long nowMillis, int idleTimeoutMinutes)
	{
		if (activeTask == null)
		{
			return;
		}
		activeTask.addActualKills(literalKills);
		activeTask.addKillSlayerXp(slayerXp);
		if (literalKills > 0 || slayerXp > 0)
		{
			activeTimeTracker.recordActivity(activeTask, nowMillis, idleTimeoutMinutes);
			checkpointIfDue(nowMillis);
		}
	}

	public void applyBonusXp(int slayerXp, long nowMillis, int idleTimeoutMinutes)
	{
		if (activeTask == null || completionConfirmedAtMillis == 0L || slayerXp <= 0)
		{
			return;
		}
		activeTask.addBonusSlayerXp(slayerXp);
		activeTimeTracker.recordActivity(activeTask, nowMillis, idleTimeoutMinutes);
		repository.saveCheckpoint(activeTask);
	}

	public void applyCannonballsUsed(int cannonballs, long nowMillis)
	{
		if (activeTask == null || cannonballs <= 0)
		{
			return;
		}
		activeTask.addCannonballsUsed(cannonballs);
		checkpointIfDue(nowMillis);
	}

	public int confirmCompletion(long nowMillis, int idleTimeoutMinutes)
	{
		if (activeTask == null || completionConfirmedAtMillis > 0L)
		{
			return 0;
		}

		int terminalProgress = Math.max(0, activeTask.getLastRemainingAmount());
		activeTask.addProgressUnits(terminalProgress);
		activeTask.setLastRemainingAmount(0);
		activeTimeTracker.recordActivity(activeTask, nowMillis, idleTimeoutMinutes);
		completionConfirmedAtMillis = nowMillis;
		activeTask.setCompletionConfirmedAtMillis(nowMillis);
		repository.saveCheckpoint(activeTask);
		return terminalProgress;
	}

	public boolean isCompletionPending()
	{
		return activeTask != null && completionConfirmedAtMillis > 0L;
	}

	public void pause()
	{
		activeTimeTracker.pause(activeTask);
		if (activeTask != null)
		{
			repository.saveCheckpoint(activeTask);
		}
	}

	public void checkpoint()
	{
		if (activeTask != null)
		{
			repository.saveCheckpoint(activeTask);
		}
	}

	public ActiveTask getActiveTask()
	{
		return activeTask;
	}

	private ActiveTask start(TaskSnapshot snapshot, long nowMillis)
	{
		return new ActiveTask(
			snapshot.getTaskName(),
			snapshot.getTaskLocation(),
			snapshot.getInitialAmount(),
			snapshot.getRemainingAmount(),
			nowMillis);
	}

	private TaskRun finish(
		TaskRunStatus status,
		long nowMillis,
		boolean separateByLocation,
		int maximumRecentRuns)
	{
		TaskRun run = activeTask.finish(status, nowMillis);
		activeTask = null;
		needsRebaselineAfterLoad = false;
		taskMissingSinceMillis = 0L;
		completionConfirmedAtMillis = 0L;
		repository.saveRun(run, separateByLocation, maximumRecentRuns);
		return run;
	}

	private static boolean sameAssignment(ActiveTask task, TaskSnapshot snapshot)
	{
		return new TaskKey(task.getTaskName(), task.getTaskLocation()).equals(
			new TaskKey(snapshot.getTaskName(), snapshot.getTaskLocation()));
	}

	private void checkpointIfDue(long nowMillis)
	{
		if (activeTask.getLastCheckpointAtMillis() == 0
			|| nowMillis - activeTask.getLastCheckpointAtMillis() >= CHECKPOINT_INTERVAL_MILLIS)
		{
			activeTask.setLastCheckpointAtMillis(nowMillis);
			repository.saveCheckpoint(activeTask);
		}
	}
}

